ALTER TABLE notification_templates MODIFY COLUMN application_id VARCHAR(191) NOT NULL, ADD CONSTRAINT chk_notification_templates_application_nonempty CHECK(application_id <> ''), DROP INDEX notification_template_uq, ADD UNIQUE KEY notification_template_scope_uq(tenant_id,application_id,code,channel,locale);
ALTER TABLE notification_deliveries MODIFY COLUMN application_id VARCHAR(191) NOT NULL, ADD CONSTRAINT chk_notification_deliveries_application_nonempty CHECK(application_id <> ''), DROP INDEX notification_delivery_key_uq, ADD UNIQUE KEY notification_delivery_scope_key_uq(tenant_id,application_id,idempotency_key);
